---- FILTER LAYER ----

, FILTER_PO_HDR as (
    SELECT *
    FROM RENAME_PO_HDR
)

, FILTER_A as (
    SELECT *
    FROM RENAME_A
    WHERE rec_src = 'USWIOC.ORCL.EBSEMTK.PO_HEADERS_ALL'
)

, FILTER_AP as (
    SELECT *
    FROM RENAME_AP
)

, FILTER_sup as (
    SELECT *
    FROM RENAME_sup
)

---- JOIN LAYER ----
, JOIN_RESULT as (
    SELECT *
    FROM FILTER_PO_HDR
    INNER JOIN FILTER_A
        ON '1' = '1'
    LEFT JOIN FILTER_AP
        ON FILTER_PO_HDR.TERMS_ID = FILTER_AP.TERM_ID
    LEFT JOIN FILTER_sup
        ON FILTER_PO_HDR.VENDOR_ID = SUP_VENDOR_ID
)

---- FINAL LAYER ----
